    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${get(this, 'modelName')}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  },

  _super: worker((action, payload) => {
    switch (action) {
      case 'downloadCSV':
        this._performDownloadCSV(payload.csv);
        break;
    }
  }),
});
